export interface LruCacheOptions<K, V> {
  // ... existing options ...
  // Sliding expiry: a fresh hit (get / getOrLoad) restarts the entry's TTL. peek / has do not. Negatives never slide.
  slidingExpiry?: boolean;
}

interface Entry<V> {
  value: V;
  weight: number;
  expiresAt: number;
  deadAt: number;
  negative: boolean;
  ttl: number | undefined; // NEW: the TTL it was stored with (to restart it)
  stale: number;           // NEW: its grace
}

private hit(key: K, entry: Entry<V>): void {
  this.counters.hits++;
  if (entry.negative) this.counters.negativeHits++;
  if (this.options.slidingExpiry && entry.ttl !== undefined && !entry.negative) {
    entry.expiresAt = this.now() + entry.ttl;
    entry.deadAt = entry.expiresAt + entry.stale; // the grace moves with the TTL
  }
  this.touch(key, entry);
}

// in store():
this.map.set(key, { value, weight, expiresAt, deadAt: expiresAt + stale, negative, ttl, stale });

