import { describe, expect, it } from "vitest";
import { LruCache } from "../src/cache.js";
import { manualClock } from "./support.js";

describe("slidingExpiry", () => {
  it("a get restarts the TTL; peek does not", () => {
    const clock = manualClock();
    const c = new LruCache<string, number>({ maxEntries: 10, ttlMs: 100, slidingExpiry: true, now: clock.now });
    c.set("a", 1);
    c.set("b", 2);
    clock.advance(60);
    expect(c.get("a")).toBe(1);  // a now expires at +160
    expect(c.peek("b")).toBe(2); // b still expires at +100
    clock.advance(40);           // +100
    expect(c.has("b")).toBe(false);
    expect(c.get("a")).toBe(1);  // restarted again: +200
    clock.advance(99);
    expect(c.peek("a")).toBe(1);
    clock.advance(1);            // +200
    expect(c.peek("a")).toBeUndefined();
  });

  it("without the option a get does not extend the TTL (today's rule)", () => {
    const clock = manualClock();
    const c = new LruCache<string, number>({ maxEntries: 10, ttlMs: 100, now: clock.now });
    c.set("a", 1);
    clock.advance(60);
    c.get("a");
    clock.advance(40);
    expect(c.get("a")).toBeUndefined();
  });

  it("a cached 'not found' never slides: it still ends at negativeTtlMs", async () => {
    const clock = manualClock();
    const c = new LruCache<string, number | null>({ maxEntries: 10, ttlMs: 1000, negativeTtlMs: 50, slidingExpiry: true, now: clock.now });
    await c.getOrLoad("ghost", async () => null);
    clock.advance(40);
    expect(c.get("ghost")).toBeNull(); // a negative hit, TTL not restarted
    clock.advance(10);
    expect(c.has("ghost")).toBe(false);
  });

  it("the grace moves with the TTL", async () => {
    const clock = manualClock();
    const c = new LruCache<string, number>({ maxEntries: 10, ttlMs: 100, staleMs: 50, slidingExpiry: true, now: clock.now });
    c.set("k", 1);
    clock.advance(90);
    c.get("k");          // fresh until +190, stale until +240
    clock.advance(140);  // +230: stale, within the grace
    expect(c.get("k")).toBeUndefined(); // get never returns stale
    expect(await c.getOrLoad("k", () => new Promise<number>(() => {}))).toBe(1); // getOrLoad serves it stale
  });
});

