// (verified: the three tests below pass against an unmodified copy of cache.ts)
import type { LoadContext, Loader, LruCache } from "./cache.js";

// Counts recent requests per key. Every `sampleSize` requests all counts are halved (aging, the idea of TinyLFU's
// reset): old popularity fades and keys whose count reaches 0 are forgotten, so the map stays bounded.
export class FrequencyAdmission<K> {
  private readonly counts = new Map<K, number>();
  private events = 0;
  constructor(readonly options: { minHits: number; sampleSize: number }) {}

  record(key: K): number {
    const n = (this.counts.get(key) ?? 0) + 1;
    this.counts.set(key, n);
    if (++this.events >= this.options.sampleSize) this.age();
    return n;
  }

  private age(): void {
    this.events = 0;
    for (const [k, n] of this.counts) {
      const half = n >> 1;
      if (half === 0) this.counts.delete(k);
      else this.counts.set(k, half);
    }
  }
}

// A key enters the LRU only once it was asked for minHits times recently. One-hit wonders (a crawler, a report
// that reads every id once) are served by the loader but never push the hot keys out.
export class AdmittingCache<K, V> {
  private readonly bypass = new Map<K, Promise<V>>(); // single flight for keys not admitted (yet)

  constructor(private readonly cache: LruCache<K, V>, private readonly admission: FrequencyAdmission<K>) {}

  getOrLoad(key: K, loader: Loader<V>): Promise<V> {
    const n = this.admission.record(key);
    if (n >= this.admission.options.minHits || this.cache.has(key)) return this.cache.getOrLoad(key, loader);
    let p = this.bypass.get(key);
    if (p === undefined) {
      // isCurrent() false = "this value will not be stored", exactly what the context means in cache.ts
      const context: LoadContext = { ttlMs: undefined, refresh: false, isCurrent: () => false };
      p = (async () => loader(new AbortController().signal, context))().finally(() => this.bypass.delete(key));
      this.bypass.set(key, p);
    }
    return p;
  }
}

