import { describe, expect, it, vi } from "vitest";
import { AdmittingCache, FrequencyAdmission } from "../src/admission.js";
import { LruCache } from "../src/cache.js";

describe("frequency admission", () => {
  it("a scan of one-time keys does not evict the hot keys", async () => {
    const lru = new LruCache<string, string>({ maxEntries: 2 });
    const c = new AdmittingCache(lru, new FrequencyAdmission<string>({ minHits: 2, sampleSize: 1000 }));
    const loader = vi.fn(async (_s: AbortSignal) => "v");
    for (const k of ["a", "a", "b", "b"]) await c.getOrLoad(k, loader); // the 2nd request of each admits it
    expect(lru.keys()).toEqual(["a", "b"]);
    for (let i = 0; i < 100; i++) await c.getOrLoad(`scan-${i}`, loader);
    expect(lru.keys()).toEqual(["a", "b"]); // nothing from the scan got in
    loader.mockClear();
    expect(await c.getOrLoad("a", loader)).toBe("v");
    expect(loader).not.toHaveBeenCalled(); // still a hit
  });

  it("concurrent requests for a key not admitted yet share ONE loader call", async () => {
    const c = new AdmittingCache(new LruCache<string, number>({ maxEntries: 10 }), new FrequencyAdmission<string>({ minHits: 100, sampleSize: 10_000 }));
    let calls = 0;
    const loader = async () => {
      calls++;
      await new Promise((r) => setTimeout(r, 5));
      return 7;
    };
    expect(await Promise.all(Array.from({ length: 10 }, () => c.getOrLoad("k", loader)))).toEqual(Array(10).fill(7));
    expect(calls).toBe(1);
  });

  it("aging: a count that halves to 0 is forgotten", async () => {
    const lru = new LruCache<string, number>({ maxEntries: 10 });
    const c = new AdmittingCache(lru, new FrequencyAdmission<string>({ minHits: 2, sampleSize: 4 }));
    for (const k of ["x", "y", "z", "w"]) await c.getOrLoad(k, async () => 1); // the 4th record halves every 1 to 0
    await c.getOrLoad("x", async () => 1); // counts as the FIRST request again
    expect(lru.has("x")).toBe(false);
    await c.getOrLoad("x", async () => 1); // second recent request: admitted
    expect(lru.has("x")).toBe(true);
  });
});

